// A fingerprint for an Artifact whose evals depend on more than its own folder: the SHA-256
// over the files below every path given (a file, or a folder walked in name order), by their
// path relative to the first path's parent and their bytes. Folders of build output, installed
// packages, generated files and the declarations themselves are not inputs.
// Usage: node fingerprint.mjs PATH...   (prints desktop:<hex>)
import { createHash } from "node:crypto";
import { readdirSync, readFileSync, statSync } from "node:fs";
import { basename, join, relative, resolve } from "node:path";

// Tauri permission references are build output too, including those of test-only plugins.
const SKIPPED = new Set([".git", "node_modules", "dist", "target", "gen", "autogenerated", ".svelte-kit"]);
// pnpm's observed hardlink/store probe briefly creates this file in the project root.
const PNPM_PROBE = /^_tmp_[0-9]+_[0-9a-f]{8}$/;
const hash = createHash("sha256");

function add(path, base, label) {
  const probe = PNPM_PROBE.test(basename(path));
  let status;
  try { status = statSync(path); }
  catch (error) {
    // The probe may already be unlinked after the directory was enumerated.
    if (probe && error.code === "ENOENT") return;
    throw error;
  }
  if (status.isDirectory()) {
    for (const name of readdirSync(path).sort()) {
      if (!SKIPPED.has(name)) add(join(path, name), base, label);
    }
  } else if (status.isFile() && !path.endsWith(".artf") && !probe) {
    hash.update(`${label}:${relative(base, path)}\0${createHash("sha256").update(readFileSync(path)).digest("hex")}\n`);
  }
}

const paths = process.argv.slice(2).map((path) => resolve(path));
if (paths.length === 0) {
  console.error("usage: node fingerprint.mjs PATH...");
  process.exit(2);
}
// Paths are named relative to the folder they are below, so a moved checkout keeps its value.
paths.forEach((path, label) => add(path, statSync(path).isDirectory() ? path : resolve(path, ".."), label));
console.log(`desktop:${hash.digest("hex")}`);
